from collections import Counter

def linefill(g):
    cnt=Counter(x for row in g for x in row)
    anchor=min(cnt, key=lambda x: (cnt[x], x))
    target=max(cnt, key=lambda x: (cnt[x], -x))
    h,w=len(g),len(g[0]); out=[row[:] for row in g]
    for r in range(h):
        ps=[c for c,x in enumerate(g[r]) if x==anchor]
        if len(ps)>=2:
            for c in range(ps[0]+1,ps[-1]):
                if g[r][c]==target: out[r][c]=3
    for c in range(w):
        ps=[r for r in range(h) if g[r][c]==anchor]
        if len(ps)>=2:
            for r in range(ps[0]+1,ps[-1]):
                if g[r][c]==target: out[r][c]=3
    return out
